<span class="line"><span style="color:#56B6C2;">dism.exe</span><span style="color:#56B6C2;"> /</span><span style="color:#ABB2BF;">online </span><span style="color:#56B6C2;">/enable-feature</span><span style="color:#56B6C2;"> /</span><span style="color:#ABB2BF;">featurename:Microsoft</span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;">Windows</span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;">Subsystem</span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;">Linux </span><span style="color:#56B6C2;">/</span><span style="color:#ABB2BF;">all </span><span style="color:#56B6C2;">/</span><span style="color:#ABB2BF;">norestart</span></span>
